// node --test render/wan-single-golden.test.mjs
// The SINGLE placement of the Wan 2.2 graph is the graph the builder made before placements existed, node for node.
//
// render/testdata/wan22-single-graphs.json holds nine graphs (the experts, loader, decode, fast, upscale and sampler
// arguments that matter) with the arguments that made them. They were generated by the builder as it stood at the 0.181.0
// release tip (3b758ce7, render/wf-wan22-i2v.mjs), BEFORE `placement` was added, and are not regenerated from the current
// builder: a change that moves any node of a single-placement graph fails here and must say so. wan-multicard.test.mjs
// compares `placement: "single"` with the default placement, which only proves the two agree with each other; this file
// is what proves they agree with what was built before (a surviving mutant of that test: the stock VAELoader replaced by
// the multi-GPU one in the single graph passed every other test of the file).
import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { buildWan22I2V } from "./wf-wan22-i2v.mjs";

const golden = JSON.parse(readFileSync(new URL("./testdata/wan22-single-graphs.json", import.meta.url), "utf8"));
const names = Object.keys(golden);

test("the golden holds the graphs it says it holds", () => {
  assert.equal(names.length, 9);
  for (const name of names) {
    const { args, graph } = golden[name];
    assert.ok(args && graph && Object.keys(graph).length > 10, name);
    assert.ok(!Object.values(graph).some((n) => /MultiGPU/.test(n.class_type) && !/DisTorch2/.test(n.class_type)), `${name}: no multi-GPU loader but the DisTorch2 ones`);
    assert.ok(!Object.values(graph).some((n) => n.class_type === "OffloadFreeForDecode"), name);
  }
});

for (const name of Object.keys(golden)) {
  test(`single placement, ${name}: the graph is the one built before placements existed`, () => {
    const { args, graph } = golden[name];
    const warned = [];
    const warn = (l) => warned.push(l);
    assert.deepEqual(buildWan22I2V({ ...args, warn }), graph, "no placement argument");
    assert.deepEqual(buildWan22I2V({ ...args, placement: "single", warn }), graph, 'placement: "single"');
    assert.deepEqual(buildWan22I2V({ ...args, placement: "single", residentGb: 9, warn }), graph, "a residentGb means nothing to the single placement");
    assert.deepEqual(warned, [], "and the single placement says nothing the base did not");
  });
}
